import nx from '@nx/eslint-plugin';
import sheriff from '@softarc/eslint-plugin-sheriff';
import { sharedConfig } from './tools/eslint/shared-config.mjs';

export default [
  ...nx.configs['flat/base'],
  ...nx.configs['flat/typescript'],
  ...nx.configs['flat/javascript'],
  ...sharedConfig,
  {
    // generated by GraphQL Codegen (`npm run codegen`)
    ignores: ['**/dist', '**/src/lib/**/generated'],
  },
  // dependency rules and `internal` encapsulation from sheriff.config.ts
  sheriff.configs.all,
  {
    files: ['**/*.ts', '**/*.tsx', '**/*.js', '**/*.jsx'],
    rules: {
      '@nx/enforce-module-boundaries': [
        'error',
        {
          // libs are buildable only so the Angular Vitest runner has a build target;
          // the app compiles them from source, so they may use non-buildable libs (api)
          enforceBuildableLibDependency: false,
          allow: [
            '^.*/eslint(\\.base)?\\.config\\.[cm]?[jt]s$',
            // build-time codegen config shared by the data-access libs
            '^.*/tools/graphql/client-codegen$',
          ],
          // dependency rules between domains and types live in sheriff.config.ts;
          // this rule still checks lazy-loaded, relative, circular and deep imports
          depConstraints: [{ sourceTag: '*', onlyDependOnLibsWithTags: ['*'] }],
        },
      ],
    },
  },
  {
    // a barrel is a lib's public API: it never exposes an `internal` folder
    // relative to the config that spreads this one, so no `libs/` prefix
    files: ['**/src/index.ts', '**/src/public-api.ts'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          patterns: [
            {
              regex: '(^|/)internal(/|$)',
              message:
                'A barrel must not import or export from an `internal` folder: that code is private to the lib.',
            },
          ],
        },
      ],
      // ng-packagr wraps a buildable lib's barrel in `export * from './index'`, which drops
      // `default`: the lib then builds on its own, but every lib that imports it fails
      'no-restricted-syntax': [
        'error',
        {
          selector: 'ExportDefaultDeclaration',
          message:
            "A barrel must not use `export default`: the built lib loses it. Use a named export and lazy-load with `import('@cv/…').then((m) => m.Page)`.",
        },
        {
          selector: 'ExportSpecifier[exported.name="default"]',
          message:
            "A barrel must not re-export `default`: the built lib loses it. Use a named export and lazy-load with `import('@cv/…').then((m) => m.Page)`.",
        },
      ],
    },
  },
  {
    files: [
      '**/*.ts',
      '**/*.tsx',
      '**/*.cts',
      '**/*.mts',
      '**/*.js',
      '**/*.jsx',
      '**/*.cjs',
      '**/*.mjs',
    ],
    // Override or add rules here
    rules: {},
  },
];
